package dev.mixer.android;
import java.util.*;import android.app.Activity;import android.widget.EditText;import android.view.inputmethod.*;
/** Identical witness runs on original accepted86 leaves and proposed v4; no derivative API reference. */
public final class AttributeBranchWitness {
 private AttributeBranchWitness(){}private static final class Fatal extends Error{private static final long serialVersionUID=1L;}
 private static boolean call(BaseInputConnection target,String family){return family.equals("commitText")?target.commitText("z",1,new TextAttribute()):target.setComposingText("z",1,new TextAttribute());}
 public static void main(String[] args){List<Object> results=new ArrayList<>();List<String> events=new ArrayList<>();for(String family:List.of("commitText","setComposingText"))for(boolean closed:new boolean[]{false,true}){EditText edit=new EditText(new Activity());edit.setText("old");edit.setSelection(3,3);BaseInputConnection target=new BaseInputConnection(edit,true);target.closed=closed;ConcreteHostProbe.reset();ConcreteHostProbe.hook=(m,p)->{events.add(m+"/"+p);if(m.equals("BaseInputConnection."+family+"WithAttributes")&&p.equals("beforeReturn"))target.closed=!closed;};results.add(call(target,family));results.add(edit.getText().toString());ConcreteHostProbe.hook=null;for(String phase:List.of("entry","beforeReturn"))for(Throwable original:List.of(new IllegalStateException("ordinary"),new Fatal())){ConcreteHostProbe.hook=(m,p)->{events.add(m+"/"+p);if(m.equals("BaseInputConnection."+family+"WithAttributes")&&p.equals(phase)){if(original instanceof Error fatal)throw fatal;throw(RuntimeException)original;}};Throwable escaped=null;try{call(target,family);}catch(RuntimeException|Error failure){escaped=failure;}results.add(escaped==original);ConcreteHostProbe.hook=null;}}System.out.println(results);System.out.println(events);}
}
